export function MicroAnimation({
  feedback = "{{feedback}}",
  simulate = {{simulate}},
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  const active = {
    scale: { transform: "scale(.9)" },
    ripple: { boxShadow: `0 0 0 8px ${accent}` },
    "colour-flash": { background: accent },
  }[feedback];
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 24, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      <button type="button" className="btn" style={{ position: "relative", overflow: "hidden", fontWeight: 600, fontSize: 14, padding: "10px 18px", borderRadius: 999, border: "1.5px solid #24143022", background: "#fff", color: "#241430", cursor: "pointer", ...(simulate ? active : {}) }}>
        &hearts; Like
      </button>
      <p style={{ margin: "14px 0 0" }}>{feedback} &middot; {duration}ms &middot; a small nudge of feedback, not a full animation</p>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .btn { transition: transform ${duration}ms ease-out, background ${duration}ms ease-out, box-shadow ${duration}ms ease-out; }
        }
      `}</style>
    </div>
  );
}
